import{_ as r,o as a,c as t,ae as n}from"./chunks/framework.BvHJbMD4.js";const f=JSON.parse('{"title":"Recherche: Die Schredder-Affäre (Reißwolf-Gate)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/schredder-affaere.md","filePath":"recherche/schredder-affaere.md"}'),i={name:"recherche/schredder-affaere.md"};function d(h,e,l,s,o,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="recherche-die-schredder-affare-reißwolf-gate" tabindex="-1">Recherche: Die Schredder-Affäre (Reißwolf-Gate) <a class="header-anchor" href="#recherche-die-schredder-affare-reißwolf-gate" aria-label="Permalink to &quot;Recherche: Die Schredder-Affäre (Reißwolf-Gate)&quot;">​</a></h1><p>Im Kontext unserer Mockumentary beleuchten wir nicht nur die historischen Machenschaften der Ära Horten, sondern auch die moderne Ethik politischer Transparenz. Ein Musterbeispiel für den Umgang mit &#39;unangenehmen Daten&#39; ist die österreichische Schredder-Affäre von 2019.</p><h2 id="der-vorfall" tabindex="-1">Der Vorfall <a class="header-anchor" href="#der-vorfall" aria-label="Permalink to &quot;Der Vorfall&quot;">​</a></h2><p>Kurz nach dem Bekanntwerden des Ibiza-Videos brachte ein enger Vertrauter des damaligen Kanzlers Sebastian Kurz unter dem Pseudonym &quot;Walter Maisinger&quot; fünf Festplatten zur Firma <em>Reisswolf</em>. Er ließ sie dreifach schreddern, nahm die Überreste wieder mit und vergaß, die Rechnung zu bezahlen – was die gesamte Aktion auffliegen ließ.</p><h2 id="ethische-einordnung-fur-unser-projekt" tabindex="-1">Ethische Einordnung für unser Projekt <a class="header-anchor" href="#ethische-einordnung-fur-unser-projekt" aria-label="Permalink to &quot;Ethische Einordnung für unser Projekt&quot;">​</a></h2><p>Für die Mockumentary ziehen wir Parallelen zwischen der &#39;Marktbereinigung&#39; Helmut Hortens und der &#39;Datenbereinigung&#39; der modernen Politik. Beides folgt dem Prinzip: <em>Was nicht mehr existiert, hat nie stattgefunden.</em></p><h3 id="fakten-check-links" tabindex="-1">Fakten-Check &amp; Links: <a class="header-anchor" href="#fakten-check-links" aria-label="Permalink to &quot;Fakten-Check &amp; Links:&quot;">​</a></h3><ul><li><strong>Der Ablauf:</strong> Eine konspirative Aktion, die laut ÖVP nur dem &quot;Schutz sensibler Daten&quot; diente, von Kritikern jedoch als Vernichtung von Beweismitteln zur Ibiza-Affäre gewertet wurde.</li><li><strong>Wikipedia-Artikel:</strong> <a href="https://de.wikipedia.org/wiki/Schredder-Aff%C3%A4re" target="_blank" rel="noreferrer">Chronik der Schredder-Affäre</a></li><li><strong>Hintergrundbericht (Kontrast.at):</strong> <a href="https://kontrast.at/schredder-affaere-oevp-festplatten-reisswolf/" target="_blank" rel="noreferrer">Festplatten-Vernichtung im Detail</a></li></ul><h3 id="video-material" tabindex="-1">Video-Material: <a class="header-anchor" href="#video-material" aria-label="Permalink to &quot;Video-Material:&quot;">​</a></h3><p>In der Mockumentary planen wir, die Szenen der Festplatten-Vernichtung satirisch nachzustellen. Hier ist das Original-Thema in den Medien:</p><ul><li><a href="https://www.youtube.com/results?search_query=%C3%B6vp+schredder+video" target="_blank" rel="noreferrer">YouTube-Suche: ÖVP Schredder Video</a></li></ul><h3 id="parallele-zum-horten-projekt" tabindex="-1">Parallele zum Horten-Projekt: <a class="header-anchor" href="#parallele-zum-horten-projekt" aria-label="Permalink to &quot;Parallele zum Horten-Projekt:&quot;">​</a></h3><p>Genau wie die Horten-Spenden in winzige Stücke zerlegt wurden, um sie unsichtbar zu machen (Pointillismus des Kapitals), wurden hier Festplatten in winzige Stücke zerlegt. Es ist eine Ästhetik der Zerstörung, die wir in Teil 4 filmisch aufgreifen.</p><hr><p><em>Quelle der Recherche: Investigative Berichte von Standard, Falter und internationalen Medien.</em></p>',15)])])}const m=r(i,[["render",d]]);export{f as __pageData,m as default};
